private fun summary(r:MarketResult)="${r.exactGoogle.size+r.exactEbay.size} exact • ${r.similarGoogle.size+r.similarEbay.size} similar • ${r.components.count{it.value>0}} components • ${r.rejected.size} rejected${if(r.searches.size>1)" • ${r.searches.size} safe searches" else ""}"
@Composable fun Valuation(r:MarketResult,ask:String,gp:Double,estimateRate:Double){val exactNew=median(r.exactGoogle.map{it.price});val exactUsed=median(r.exactEbay.map{it.price});val exactEvidence=r.exactGoogle.isNotEmpty()||r.exactEbay.isNotEmpty();val used=when{exactUsed>0->exactUsed;exactNew>0->exactNew*estimateRate;else->0.0};val componentEstimate=r.components.sumOf{it.value};val primary=if(exactEvidence)used else componentEstimate;val max=if(primary>0)primary*(1-gp) else 0.0;val a=ask.toDoubleOrNull()?:0.0;if(exactEvidence&&used>0){Metrics(listOf("NEW RETAIL" to exactNew,"USED VALUE" to used,"MAX BUY" to max,"AVERAGE RESULT" to used));Verdict(if(a<=0)"PRICE READY" else if(a<=max)"BUY" else if(a<=max*1.1)"NEGOTIATE" else "PASS")}else{Block("EXACT MARKET VALUE UNAVAILABLE","No verified exact-brand/model listing was found. Broader searches may provide similar evidence, but they cannot drive the primary value. A conservative component fallback is used only when CPU/GPU/RAM/storage evidence can be independently validated.");if(componentEstimate>0){Metrics(listOf("COMPONENT ESTIMATE" to componentEstimate,"COMPONENT MAX BUY" to max));ComponentBreakdown(r.components);Verdict(if(a<=0)"LOW CONFIDENCE" else if(a<=max)"BUY — LOW CONFIDENCE" else if(a<=max*1.1)"NEGOTIATE — LOW CONFIDENCE" else "PASS — LOW CONFIDENCE")}else Verdict("LOW CONFIDENCE")};Confidence(r);MultiSourceEvidence(r,estimateRate);if(r.searches.size>1)Block("SEARCH COVERAGE",r.searches.joinToString("\n") { "• $it" });Evidence(r)}
@Composable fun ComponentBreakdown(items:List<ComponentValue>){Text("Component valuation breakdown",fontSize=21.sp,fontWeight=FontWeight.Black);items.forEach{x->Block(x.label,"${if(x.value>0)money(x.value) else "No validated value"} • ${x.evidence.size} matched result${if(x.evidence.size==1)"" else "s"}\nSearch: ${x.query}")}}
@Composable fun Confidence(r:MarketResult){val exact=r.exactGoogle.size+r.exactEbay.size;val similar=r.similarGoogle.size+r.similarEbay.size;val componentCount=r.components.count{it.value>0};val label=when{exact>=2->"HIGH";exact==1->"MEDIUM";componentCount>=3->"LOW — COMPONENT BASED";similar>0||componentCount>0->"LOW";else->"UNAVAILABLE"};Block("MATCH QUALITY","Exact matches: $exact\nSimilar/spec matches: $similar\nValidated components: $componentCount/${r.components.size}\nRejected results: ${r.rejected.size}\nConfidence: $label")}
@Composable fun Evidence(r:MarketResult){Section("Exact eBay AU used comparables",r.exactEbay,"No exact used listings found.");Section("Exact Google Shopping AU new offers",r.exactGoogle,"No exact new listings found.");if(r.components.any{it.evidence.isNotEmpty()}){Text("Validated component evidence — fallback only",fontSize=21.sp,fontWeight=FontWeight.Black);r.components.filter{it.evidence.isNotEmpty()}.forEach{x->Section(x.label,x.evidence,"")}};Section("Similar whole-PC results — excluded from valuation",r.similarEbay+r.similarGoogle,"No similar results retained.");if(r.rejected.isNotEmpty())Section("Rejected results — not used",r.rejected.take(8),"")}
