@Composable fun Metrics(items:List<Pair<String,Double>>){Column(verticalArrangement=Arrangement.spacedBy(10.dp)){items.chunked(2).forEach{row->Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp)){row.forEach{(k,v)->Card(colors=CardDefaults.cardColors(containerColor=Card),modifier=Modifier.weight(1f)){Column(Modifier.padding(16.dp)){Text(k,color=Color.Gray,fontSize=11.sp,fontWeight=FontWeight.Bold);Text(if(v>0)money(v) else "—",fontSize=23.sp,fontWeight=FontWeight.Black)}}};if(row.size==1)Spacer(Modifier.weight(1f))}}}}
private fun parse(obj:JSONObject?,query:String):List<Listing>{if(obj==null)return emptyList();val a=obj.optJSONArray("items")?:JSONArray();val out=mutableListOf<Listing>();for(i in 0 until a.length()){val x=a.optJSONObject(i)?:continue;val title=x.optString("title",x.optString("name","Untitled result"));val p=listOf("deliveredPrice","price","itemPrice").asSequence().map{x.optDouble(it,0.0)}.firstOrNull{it>0}?:0.0;val(tier,score,reasons)=classify(query,title);out+=Listing(title,p,x.optString("seller",x.optString("store",x.optString("source",x.optString("merchant","")))),x.optString("url",x.optString("link",x.optString("itemWebUrl",""))),x.optString("condition",""),tier,score,reasons)};return out}
private fun rawListings(obj:JSONObject?):List<Listing>{if(obj==null)return emptyList();val a=obj.optJSONArray("items")?:JSONArray();val out=mutableListOf<Listing>();for(i in 0 until a.length()){val x=a.optJSONObject(i)?:continue;val p=listOf("deliveredPrice","price","itemPrice").asSequence().map{x.optDouble(it,0.0)}.firstOrNull{it>0}?:0.0;if(p<=0)continue;out+=Listing(x.optString("title",x.optString("name","Untitled result")),p,x.optString("seller",x.optString("store",x.optString("source",x.optString("merchant","")))),x.optString("url",x.optString("link",x.optString("itemWebUrl",""))),x.optString("condition",""),MatchTier.SIMILAR,100,"Component match")};return out}
private suspend fun request(query:String,limit:Int=40):JSONObject=withContext(Dispatchers.IO){val c=(URL(API).openConnection() as HttpURLConnection).apply{requestMethod="POST";connectTimeout=15000;readTimeout=20000;doOutput=true;setRequestProperty("Content-Type","application/json")};val body=JSONObject().put("query",query).put("limit",limit).put("australiaOnly",true).put("mode","device").toString();c.outputStream.use{it.write(body.toByteArray())};val code=c.responseCode;val text=(if(code in 200..299)c.inputStream else c.errorStream).bufferedReader().use{it.readText()};val root=JSONObject(text);if(code !in 200..299||!root.optBoolean("success"))throw IllegalStateException(root.optString("error","HTTP $code"));root}
private fun componentMatch(label:String,needle:String,x:Listing):Boolean{val t=norm(x.title);val n=norm(needle);val bad=Regex("\\b(wanted|box only|empty box|manual|sticker|decal|backplate|waterblock|heatsink|cooler|fan only|cable|adapter|bracket|for parts|faulty|repair)\\b").containsMatchIn(t);if(bad)return false;return when(label){"CPU"->t.contains(Regex("\\b${Regex.escape(n)}\\b"))&&!Regex("\\b(desktop pc|gaming pc|laptop|computer system|workstation)\\b").containsMatchIn(t);"GPU"->t.contains(n)&&!Regex("\\b(desktop pc|gaming pc|laptop|computer system|workstation)\\b").containsMatchIn(t);"RAM"->t.contains(Regex("\\b${Regex.escape(n)}\\s*gb\\b"))&&Regex("\\b(ram|memory|ddr[345])\\b").containsMatchIn(t);"STORAGE"->t.contains(n)&&Regex("\\b(ssd|nvme|solid state|m 2)\\b").containsMatchIn(t);else->false}}
private suspend fun componentValue(label:String,needle:String):ComponentValue{if(needle.isBlank())return ComponentValue(label,"",0.0,emptyList());val query=when(label){"CPU"->"$needle processor";"GPU"->"$needle graphics card";"RAM"->"$needle GB DDR4 RAM kit";else->"$needle SSD NVMe"};return runCatching{val root=request(query,30);val all=rawListings(root.optJSONObject("google"))+rawListings(root.optJSONObject("ebay"));val matched=dedupe(all.filter{componentMatch(label,needle,it)});ComponentValue(label,query,median(matched.map{it.price}),matched)}.getOrElse{ComponentValue(label,query,0.0,emptyList())}}
private suspend fun market(q:String):MarketResult=coroutineScope{val queries=broadenQueries(q);val roots=queries.map{query->async{query to request(query)}}.awaitAll();val eg=mutableListOf<Listing>();val ee=mutableListOf<Listing>();val sg=mutableListOf<Listing>();val se=mutableListOf<Listing>();val rej=mutableListOf<Listing>();for((query,root) in roots){val g=parse(root.optJSONObject("google"),q);val e=parse(root.optJSONObject("ebay"),q);eg+=g.filter{it.tier==MatchTier.EXACT};ee+=e.filter{it.tier==MatchTier.EXACT};sg+=g.filter{it.tier==MatchTier.SIMILAR};se+=e.filter{it.tier==MatchTier.SIMILAR};rej+=(g+e).filter{it.tier==MatchTier.REJECTED}};val f=features(q);val comps=listOf(async{componentValue("CPU",f.cpu)},async{componentValue("GPU",f.gpu)},async{componentValue("RAM",f.ram)},async{componentValue("STORAGE",f.storage)}).awaitAll();MarketResult(dedupe(eg),dedupe(ee),dedupe(sg),dedupe(se),dedupe(rej),comps,queries)}
@Composable fun MultiSourceEvidence(r:MarketResult,estimateRate:Double){val g=median(r.exactGoogle.map{it.price});val e=median(r.exactEbay.map{it.price});val derived=if(e>0)e else if(g>0)g*estimateRate else 0.0;Block("SOURCE CROSS-CHECK","Google Shopping exact median: ${if(g>0)money(g) else "Unavailable"}\neBay AU exact median: ${if(e>0)money(e) else "Unavailable"}\nUsed-value basis: ${if(derived>0)money(derived) else "Unavailable"}")}
